#pragma once
// Exact cache-budgeted layout planner.
//
// For every version the planner minimises the scalarised pair
//   work * 2^16 + image_pages
// which is exactly lexicographic (minimum work, then minimum pages) because
// any legal request stays far below 2^16 total image pages.  The interval
// dynamic program carries the resident-page budget, so tree topology, node
// encodings and residency are chosen jointly; the per-case page budget is then
// shared across all immutable versions by a small knapsack.
#include <algorithm>
#include <cstdint>
#include <stdexcept>
#include <string>
#include <vector>
#include "engine.hpp"

static const i128 PLAN_BIG = (i128)1 << 16;
static const i128 PLAN_INF = (i128)1 << 120;

struct PlanBurst { long long repeat; std::vector<int> idx; };
struct PlanVer {
    int R;
    std::vector<Key> starts;
    std::vector<long long> hops;
    std::vector<PlanBurst> bursts;
};
struct PlanCosts { int C; long long hit, miss; long long dec[3]; };

struct PlanDec {
    int mode, cached, b, P;
    std::vector<int> cs, ce, buds;   // child ranges and budgets
};

struct VersionPlan {
    std::vector<i128> dp;    // ((i*(R+1)+j)*(C+1)+c)
    std::vector<PlanDec> dec;
    std::vector<i128> phi;   // C+1 scalarised optima for budgets 0..C
    int R, C;
    i128 at(int i, int j, int c) const { return dp[((size_t)i * (R + 1) + j) * (C + 1) + c]; }
    const PlanDec& pick(int i, int j, int c) const { return dec[((size_t)i * (R + 1) + j) * (C + 1) + c]; }
};

struct Opt { int b, mode, P; long long coeff; };

static inline long long plan_ceil(long long a, long long b) { return (a + b - 1) / b; }

static std::vector<Opt> interval_options(const std::vector<Key>& starts, int i, int j,
                                         const PlanCosts& pc) {
    std::vector<Opt> out;
    int len = j - i;
    Key spread = starts[j - 1] - starts[i];
    bool ok1 = spread < (((Key)1) << 64);
    bool ok2 = spread < (((Key)1) << 32);
    for (int mode = 0; mode < 3; ++mode) {
        if (mode == 1 && !ok1) continue;
        if (mode == 2 && !ok2) continue;
        if (len <= 8) {                       // leaf over len runs
            unsigned k = (unsigned)len;
            unsigned used = 32u + k * (unsigned)IMG_WIDTH[mode];
            Opt o; o.b = 0; o.mode = mode; o.P = (int)((used + 63u) / 64u);
            o.coeff = plan_ceil((long long)k, IMG_LANES[mode]) + pc.dec[mode];
            out.push_back(o);
        }
        int bmax = std::min(9, len);
        for (int b = 2; b <= bmax; ++b) {     // internal node with b children
            unsigned k = (unsigned)(b - 1);
            unsigned used = 32u + 4u * (unsigned)b + k * (unsigned)IMG_WIDTH[mode];
            Opt o; o.b = b; o.mode = mode; o.P = (int)((used + 63u) / 64u);
            o.coeff = plan_ceil((long long)k, IMG_LANES[mode]) + pc.dec[mode];
            out.push_back(o);
        }
    }
    return out;
}

static void plan_version(const PlanVer& v, const PlanCosts& pc, VersionPlan& vp) {
    int R = v.R, C = pc.C;
    if (R < 1 || R > 64) throw std::runtime_error("plan runs");
    vp.R = R; vp.C = C;
    std::vector<i128> Q((size_t)R * R, 0), T((size_t)R * R, 0);
    for (size_t bi = 0; bi < v.bursts.size(); ++bi) {
        const PlanBurst& b = v.bursts[bi];
        std::vector<int> cnt((size_t)R + 1, 0);
        for (int i = 0; i <= R; ++i) {
            int n = 0;
            for (size_t k = 0; k < b.idx.size(); ++k) if (b.idx[k] < i) ++n;
            cnt[(size_t)i] = n;
        }
        for (int i = 0; i < R; ++i)
            for (int j = i + 1; j <= R; ++j) {
                int d = cnt[(size_t)j] - cnt[(size_t)i];
                Q[(size_t)i * R + j] += (i128)b.repeat * d;
                if (d) T[(size_t)i * R + j] += (i128)b.repeat;
            }
    }
    size_t W = (size_t)(C + 1);
    size_t S = (size_t)(R + 1) * (R + 1) * W;
    vp.dp.assign(S, PLAN_INF);
    vp.dec.resize(S);
    std::vector<std::vector<Opt> > opts((size_t)R * R);
    std::vector<i128> qv((size_t)R * R), tv((size_t)R * R);
    for (int i = 0; i < R; ++i)
        for (int j = i + 1; j <= R; ++j) {
            opts[(size_t)i * R + j] = interval_options(v.starts, i, j, pc);
            qv[(size_t)i * R + j] = Q[(size_t)i * R + j];
            tv[(size_t)i * R + j] = T[(size_t)i * R + j];
        }
    const bool helps = pc.miss > pc.hit;
    std::vector<i128> chain(10 * (size_t)(R + 1) * W, PLAN_INF);
    std::vector<int> argk(10 * (size_t)(R + 1) * W, -1), argc(10 * (size_t)(R + 1) * W, 0);
#define DP(i,j,c) vp.dp[((size_t)(i) * (R + 1) + (j)) * W + (c)]
#define DE(i,j,c) vp.dec[((size_t)(i) * (R + 1) + (j)) * W + (c)]
#define CH(b,t,c) chain[((size_t)(b) * (R + 1) + (t)) * W + (c)]
#define CK(b,t,c) argk[((size_t)(b) * (R + 1) + (t)) * W + (c)]
#define CC(b,t,c) argc[((size_t)(b) * (R + 1) + (t)) * W + (c)]
    for (int i = R - 1; i >= 0; --i) {
        std::fill(chain.begin(), chain.end(), PLAN_INF);
        std::fill(argk.begin(), argk.end(), -1);
        std::fill(argc.begin(), argc.end(), 0);
        for (int t = i + 1; t <= R; ++t) {
            int L = t - i;
            int cmax = std::min(C, 4 * (2 * L - 1));
            int bmax = std::min(9, L);
            for (int b = 2; b <= bmax; ++b) {
                for (int c = 0; c <= cmax; ++c) {
                    i128 best = PLAN_INF; int bk = -1, bc = 0;
                    for (int k = i + b - 1; k <= t - 1; ++k) {
                        int cap1 = std::min(c, std::min(C, 4 * (2 * (k - i) - 1)));
                        int cap2 = std::min(c, std::min(C, 4 * (2 * (t - k) - 1)));
                        int lo = std::max(0, c - cap2), hi = std::min(c, cap1);
                        for (int c1 = lo; c1 <= hi; ++c1) {
                            i128 a = CH(b - 1, k, c1);
                            if (a >= PLAN_INF) continue;
                            i128 d = DP(k, t, c - c1);
                            if (d >= PLAN_INF) continue;
                            i128 val = a + d;
                            if (val < best) { best = val; bk = k; bc = c1; }
                        }
                    }
                    CH(b, t, c) = best; CK(b, t, c) = bk; CC(b, t, c) = bc;
                }
            }
            const std::vector<Opt>& os = opts[(size_t)i * R + t];
            i128 tt = tv[(size_t)i * R + t], qq = qv[(size_t)i * R + t];
            for (int c = 0; c <= cmax; ++c) {
                i128 best = PLAN_INF; PlanDec bd;
                bd.mode = 0; bd.cached = 0; bd.b = 0; bd.P = 1;
                for (size_t oi = 0; oi < os.size(); ++oi) {
                    const Opt& o = os[oi];
                    for (int cached = 0; cached < 2; ++cached) {
                        if (cached && (!helps || o.P > c)) continue;
                        int rest = c - (cached ? o.P : 0);
                        i128 work = tt * (cached ? pc.hit : pc.miss) * o.P + (i128)o.coeff * qq;
                        i128 val = work * PLAN_BIG + o.P;
                        std::vector<int> scs, sce, sbud;
                        if (o.b) {
                            int cl = std::min(rest, cmax);
                            i128 sub = CH(o.b, t, cl);
                            if (sub >= PLAN_INF) continue;
                            val += sub;
                            int tcur = t, bcur = o.b, ccur = cl;
                            bool ok = true;
                            while (bcur > 1) {
                                int k = CK(bcur, tcur, ccur);
                                if (k < 0) { ok = false; break; }
                                int c1 = CC(bcur, tcur, ccur);
                                scs.push_back(k); sce.push_back(tcur); sbud.push_back(ccur - c1);
                                tcur = k; bcur -= 1; ccur = c1;
                            }
                            if (!ok) continue;
                            scs.push_back(i); sce.push_back(tcur); sbud.push_back(ccur);
                            std::reverse(scs.begin(), scs.end());
                            std::reverse(sce.begin(), sce.end());
                            std::reverse(sbud.begin(), sbud.end());
                            for (int z = 0; z < o.b; ++z)
                                if (scs[z] >= sce[z]) { ok = false; break; }
                            if (!ok || scs[0] != i || sce[o.b - 1] != t) continue;
                            for (int z = 0; z + 1 < o.b; ++z)
                                if (sce[z] != scs[z + 1]) { ok = false; break; }
                            if (!ok) continue;
                        }
                        if (val < best) {
                            best = val;
                            bd.mode = o.mode; bd.cached = cached; bd.b = o.b; bd.P = o.P;
                            bd.cs.swap(scs); bd.ce.swap(sce); bd.buds.swap(sbud);
                        }
                    }
                }
                if (best >= PLAN_INF) throw std::runtime_error("plan infeasible");
                DP(i, t, c) = best;
                DE(i, t, c) = bd;
            }
            for (int c = cmax + 1; c <= C; ++c) { DP(i, t, c) = DP(i, t, cmax); DE(i, t, c) = DE(i, t, cmax); }
            for (int c = 0; c <= C; ++c) CH(1, t, c) = DP(i, t, c);
        }
    }
#undef DP
#undef DE
#undef CH
#undef CK
#undef CC
    i128 pages = (i128)1 + (4 * (i128)R + 63) / 64;
    vp.phi.assign((size_t)C + 1, PLAN_INF);
    for (int c = 0; c <= C; ++c) vp.phi[(size_t)c] = vp.at(0, R, c) + pages;
}

static void plan_reconstruct(const VersionPlan& vp, int i, int j, int c, std::vector<Layout>& out) {
    const PlanDec& d = vp.pick(i, j, c);
    Layout n; n.lo = i; n.span = j - i; n.mode = d.mode; n.cached = d.cached;
    size_t self = out.size();
    out.push_back(n);
    int kids = (int)d.cs.size();
    for (int z = 0; z < kids; ++z) plan_reconstruct(vp, d.cs[z], d.ce[z], d.buds[z], out);
    for (int z = 0; z < kids; ++z) out[self].children.push_back((int)(self + 1 + z));
}

// Verify breadth-first numbering and legal-tree rules for one version layout.
static void plan_check(const std::vector<Key>& starts, const std::vector<Layout>& nodes) {
    int R = (int)starts.size();
    if (nodes.empty() || nodes.size() > (size_t)(2 * R - 1)) throw std::runtime_error("plan nodes");
    if (nodes[0].lo != 0 || nodes[0].span != R) throw std::runtime_error("plan root");
    std::vector<int> end(nodes.size());
    for (size_t i = 0; i < nodes.size(); ++i) {
        const Layout& n = nodes[i];
        if (n.lo < 0 || n.span < 1 || n.lo + n.span > R) throw std::runtime_error("plan range");
        if (n.mode < 0 || n.mode > 2 || n.cached < 0 || n.cached > 1) throw std::runtime_error("plan tag");
        end[i] = n.lo + n.span;
        size_t b = n.children.size();
        if (b == 0) { if (n.span > 8) throw std::runtime_error("plan leaf"); }
        else {
            if (b < 2 || b > 9 || b > (size_t)n.span) throw std::runtime_error("plan fanout");
            int cursor = n.lo;
            for (size_t c = 0; c < b; ++c) {
                int id = n.children[c];
                if (id <= (int)i || id >= (int)nodes.size()) throw std::runtime_error("plan order");
                if (nodes[id].lo != cursor) throw std::runtime_error("plan partition");
                if (end[id] > end[i]) throw std::runtime_error("plan containment");
                cursor = end[id];
            }
            if (cursor != end[i]) throw std::runtime_error("plan cover");
        }
    }
    // breadth-first order check: level by level index ranges must increase
    std::vector<int> q; q.push_back(0);
    for (size_t k = 0; k < q.size(); ++k) {
        if (q[k] != (int)k) throw std::runtime_error("plan bfs");
        const Layout& n = nodes[q[k]];
        for (size_t c = 0; c < n.children.size(); ++c) q.push_back(n.children[c]);
    }
    if (q.size() != nodes.size()) throw std::runtime_error("plan reachable");
}
